{"code": "export async function main(input: {}) {
  const res = await sdk.sentry.listIssues({ project: "web" });
  const issues = res.issues ?? [];
  const out = [];
  for (const iss of issues) {
    const ev = await sdk.sentry.listIssueEvents({ issueId: iss.id });
    const events = ev.events ?? [];
    out.push({
      shortId: iss.shortId,
      count: iss.count,
      status: iss.status,
      latestRelease: events.length > 0 ? events[0].release : null,
      _ts: events.length > 0 ? events[0].timestamp : null,
      _n: events.length,
    });
  }
  out.sort((a, b) => b.count - a.count);
  return { total: issues.length, rows: out };
}", "input": {}}

{"code": "export async function main(input: {}) {
  const res = await sdk.sentry.listIssues({ project: "web" });
  const issues = res.issues ?? [];
  const rows = [];
  for (const iss of issues) {
    const ev = await sdk.sentry.listIssueEvents({ issueId: iss.id });
    const events = [...(ev.events ?? [])].sort((a, b) => (a.timestamp < b.timestamp ? 1 : a.timestamp > b.timestamp ? -1 : 0));
    rows.push({
      shortId: iss.shortId,
      count: iss.count,
      status: iss.status,
      latestRelease: events.length > 0 ? events[0].release : null,
    });
  }
  rows.sort((a, b) => b.count - a.count);
  return rows;
}", "input": {}}
